package main
import("crypto/tls";"net/http";"time";"fmt";"io";"net";"context")
func main(){for _,ip:=range []string{"109.173.40.247","109.120.141.60"}{for _,classic:=range []bool{false,true}{for _,path:=range []string{"/v2/","/service/token?service=harbor-registry"}{cfg:=&tls.Config{MinVersion:tls.VersionTLS12};if classic{cfg.CurvePreferences=[]tls.CurveID{tls.X25519,tls.CurveP256}};tr:=&http.Transport{TLSClientConfig:cfg,TLSHandshakeTimeout:6*time.Second,DialContext:func(c context.Context,n,a string)(net.Conn,error){return (&net.Dialer{Timeout:6*time.Second}).DialContext(c,n,net.JoinHostPort(ip,"443"))}};c:=http.Client{Transport:tr,Timeout:8*time.Second};start:=time.Now();r,e:=c.Get("https://harbor.socrat.alchemmist.xyz"+path);if e!=nil{fmt.Printf("ip=%s classic=%t endpoint=%s error=%v elapsed=%v\n",ip,classic,path,e,time.Since(start))}else{io.Copy(io.Discard,io.LimitReader(r.Body,16384));r.Body.Close();fmt.Printf("ip=%s classic=%t endpoint=%s status=%d tls=%x elapsed=%v\n",ip,classic,path,r.StatusCode,r.TLS.Version,time.Since(start))};tr.CloseIdleConnections()}}}}
